	<script>
		// ============================
		// 1. 配置与状态
		// ============================
		const CURRENT_TIME = "2026-06-10";
		const CURRENT_LOCATION = "Shenzhen";

		let currentSessionId = null;
		const sessions = {};

		// ============================
		// 2. DOM 元素
		// ============================
		const newChatBtn = document.getElementById('newChatBtn');
		const sessionListEl = document.getElementById('sessionList');
		const chatContainer = document.getElementById('chatArea');
		const messageInput = document.getElementById('messageInput');
		const sendButton = document.getElementById('sendButton');
		const typingIndicator = document.getElementById('typingIndicator');
		const modelSelect = document.getElementById('modelSelect');

		// ============================
		// 3. 辅助函数
		// ============================
		function formatTime(date) {
			if (!(date instanceof Date)) date = new Date(date);
			return date.getHours().toString().padStart(2, '0') + ':' + 
				   date.getMinutes().toString().padStart(2, '0') + ':' +
				   date.getSeconds().toString().padStart(2, '0');
		}

		function appendMessage(sender, text, msgType = 'chat') {
			if (msgType === 'think') {
				// 折叠思考块 - 只折叠一次，内部用分隔符
				const block = document.createElement('div');
				block.className = 'think-block';
				block.innerHTML = `
					<div class="think-header" onclick="this.parentElement.classList.toggle('open')">
						<span class="think-arrow">&#9654;</span>
						<span>AI 思考过程</span>
					</div>
					<div class="think-body">${escapeHtml(text)}</div>
				`;
				chatContainer.insertBefore(block, typingIndicator);
				chatContainer.scrollTop = chatContainer.scrollHeight;
				return;
			}
			const msgDiv = document.createElement('div');
			msgDiv.className = `message ${sender}-message`;
			const bubble = document.createElement('div');
			bubble.className = 'bubble';
			bubble.innerHTML = renderMarkdown(text);
			const timeSpan = document.createElement('div');
			timeSpan.className = 'message-time';
			timeSpan.textContent = formatTime(new Date());
			msgDiv.appendChild(bubble);
			msgDiv.appendChild(timeSpan);
			chatContainer.insertBefore(msgDiv, typingIndicator);
			chatContainer.scrollTop = chatContainer.scrollHeight;
		}

		function escapeHtml(str) {
			const div = document.createElement('div');
			div.textContent = str;
			return div.innerHTML;
		}

		function renderMarkdown(text) {
			let html = escapeHtml(text);
			html = html.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
			html = html.replace(/\*(.+?)\*/g, '<em>$1</em>');
			html = html.replace(/```([\s\S]*?)```/g, '<pre><code>$1</code></pre>');
			html = html.replace(/`([^`]+)`/g, '<code>$1</code>');
			html = html.replace(/\n/g, '<br>');
			return html;
		}

		function generateSessionId() {
			return 'session_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);
		}

		// ============================
		// 4. 会话管理
		// ============================
		function clearChatArea() {
			const messages = chatContainer.querySelectorAll('.message, .think-block');
			messages.forEach(el => el.remove());
		}

		function renderChatHistory(messages) {
			clearChatArea();
			if (!messages || messages.length === 0) {
				appendMessage('system', '开始新对话吧！');
				return;
			}
			messages.forEach(msg => {
				appendMessage(msg.sender, msg.text, msg.msgType || 'chat');
			});
		}

		function renderSessionList() {
			sessionListEl.innerHTML = '';
			const keys = Object.keys(sessions);
			if (keys.length === 0) {
				sessionListEl.innerHTML = '<li class="empty-state">暂无会话</li>';
				return;
			}
			keys.forEach(id => {
				const session = sessions[id];
				const li = document.createElement('li');
				li.className = 'session-item' + (id === currentSessionId ? ' active' : '');
				li.innerHTML = `
					<span class="session-title">${escapeHtml(session.title)}</span>
					<button class="delete-session-btn" data-session-id="${id}" title="删除会话">✕</button>
				`;
				li.querySelector('.session-title').addEventListener('click', () => switchSession(id));
				li.querySelector('.delete-session-btn').addEventListener('click', (e) => {
					e.stopPropagation();
					deleteSessionById(id);
				});
				sessionListEl.appendChild(li);
			});
		}

		async function loadSessions() {
			try {
				const res = await fetch('/api/sessions');
				const data = await res.json();
				if (data.success && data.sessions) {
					data.sessions.forEach(s => {
						sessions[s.id] = {
							id: s.id,
							title: s.title,
							messages: s.messages || [],
							createdAt: new Date(s.created_at)
						};
					});
					const keys = Object.keys(sessions);
					if (keys.length > 0) {
						currentSessionId = keys[0];
						await switchSession(keys[0]);
					}
				}
			} catch (error) {
				console.error('加载会话列表失败:', error);
			}
		}

		async function switchSession(sessionId) {
			try {
				const res = await fetch(`/api/sessions/${sessionId}`);
				const data = await res.json();
				if (!data.success) throw new Error(data.message);
				currentSessionId = sessionId;
				if (!sessions[sessionId]) {
					sessions[sessionId] = { id: sessionId, title: '会话', messages: [], createdAt: new Date() };
				}
				sessions[sessionId].messages = data.messages || [];
				renderSessionList();
				renderChatHistory(sessions[sessionId].messages);
			} catch (error) {
				console.error("切换会话失败:", error);
				appendMessage('ai', `加载会话失败：${error.message}`);
			}
		}

		async function saveSessionToBackend(sessionId) {
			try {
				const sessionData = sessions[sessionId];
				await fetch('/api/sessions', {
					method: 'POST',
					headers: { 'Content-Type': 'application/json' },
					body: JSON.stringify({
						id: sessionData.id,
						title: sessionData.title,
						messages: sessionData.messages,
						created_at: sessionData.createdAt.toISOString()
					})
				});
			} catch (error) {
				console.error('保存会话失败:', error);
			}
		}

		async function createNewSession() {
			const sessionId = generateSessionId();
			const sessionTitle = `新对话 ${new Date().toLocaleTimeString()}`;
			sessions[sessionId] = {
				id: sessionId,
				title: sessionTitle,
				messages: [],
				createdAt: new Date()
			};
			currentSessionId = sessionId;
			renderSessionList();
			clearChatArea();
			appendMessage('system', `会话 [${sessionTitle}] 已启动`);
			await saveSessionToBackend(sessionId);
			return sessionId;
		}

		async function deleteSessionById(sessionId) {
			if (!confirm('确定要删除此会话吗？')) return;
			try {
				const res = await fetch(`/api/sessions/${sessionId}`, { method: 'DELETE' });
				const data = await res.json();
				if (!data.success) throw new Error(data.message);
				delete sessions[sessionId];
				if (currentSessionId === sessionId) {
					const keys = Object.keys(sessions);
					if (keys.length > 0) {
						currentSessionId = keys[0];
						await switchSession(keys[0]);
					} else {
						currentSessionId = null;
						clearChatArea();
					}
				}
				renderSessionList();
			} catch (error) {
				console.error('删除会话失败:', error);
				appendMessage('ai', `删除会话失败：${error.message}`);
			}
		}

		// ============================
		// 5. 发送消息
		// ============================
		async function sendMessage() {
			const text = messageInput.value.trim();
			if (!text || !currentSessionId) return;
			appendMessage('user', text);
			messageInput.value = '';
			typingIndicator.style.display = 'flex';

			try {
				const modelValue = modelSelect.value;
				let modelChoice = null;
				if (modelValue) {
					try {
						modelChoice = JSON.parse(modelValue);
					} catch(e) { console.error("模型解析失败", e); }
				}
				const response = await fetch('/api/chat', {
					method: 'POST',
					headers: { 'Content-Type': 'application/json' },
					body: JSON.stringify({
						message: text,
						session_id: currentSessionId,
						model_choice: modelChoice
					})
				});
				const data = await response.json();
				typingIndicator.style.display = 'none';
				if (data.success) {
					// 渲染思考过程 - 只折叠一次，内部用分隔符
					if (data.steps && data.steps.length > 0) {
						const thinkLines = [];
						let roundIndex = 0;
						for (const s of data.steps) {
							if (s.status === '完成') continue;
							roundIndex++;
							if (roundIndex > 1) {
								thinkLines.push('-----------------第' + roundIndex + '轮-----------------');
							}
							thinkLines.push(s.step);
						}
						if (thinkLines.length > 0) {
							appendMessage('ai', thinkLines.join('\n'), 'think');
						}
					}

					// 渲染最终回复
					const aiResponse = data.message;
					appendMessage('ai', aiResponse);

					// 更新本地缓存
					if (sessions[currentSessionId]) {
						sessions[currentSessionId].messages.push({ sender: 'user', text: text, msgType: 'chat' });
						if (data.steps && data.steps.length > 0) {
							const thinkLines = [];
							let roundIndex = 0;
							for (const s of data.steps) {
								if (s.status === '完成') continue;
								roundIndex++;
								if (roundIndex > 1) {
									thinkLines.push('-----------------第' + roundIndex + '轮-----------------');
								}
								thinkLines.push(s.step);
							}
							if (thinkLines.length > 0) {
								sessions[currentSessionId].messages.push({ sender: 'ai', text: thinkLines.join('\n'), msgType: 'think' });
							}
